import{_ as e,o,c as a,a7 as r}from"./chunks/framework.Cv3pX6x0.js";const b=JSON.parse('{"title":"Contributing","description":"Ways to contribute to Axolotl-PM by reporting bugs, translating on Weblate, and submitting code through GitHub pull requests.","frontmatter":{"title":"Contributing","outline":"deep","description":"Ways to contribute to Axolotl-PM by reporting bugs, translating on Weblate, and submitting code through GitHub pull requests.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/contributing"}]]},"headers":[],"relativePath":"docs/contributing.md","filePath":"docs/contributing.md","lastUpdated":1790689997000}'),s={name:"docs/contributing.md"};function i(n,t,l,u,p,d){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Axolotl-PM will always be free and open-source, but it requires a lot of time and effort from unpaid volunteers to develop.</p><p>There are a few ways to contribute to the effort.</p><h2 id="reporting-bugs" tabindex="-1">Reporting bugs <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;Reporting bugs&quot;">​</a></h2><p>Our team makes the best effort to stop bugs from making it to releases, but sometimes things will slip through the net.</p><p>If you run into a bug, please make sure to report it so that our team can fix it.</p><p>Check out the <a href="/website/previews/9f14c22779bf/docs/issues/github-issues">Issues</a> section to find out how to make a bug report.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Please don’t assume that bugs will magically be fixed.</p><p>If you don’t report them, we may not find out about them and they won’t get fixed.</p></div><h2 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to &quot;Translations&quot;">​</a></h2><p>We provide translations for Axolotl-PM in many different languages, but since the core team doesn’t know many of them, we rely on outside contributors to add and proofread translations.</p><p>Head over to the <a href="https://translate.axolotl-pm.org" target="_blank" rel="noreferrer">Axolotl-PM Weblate project</a> to get started.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Submitted translations require approval from a proofreader to be released in Axolotl-PM.</p><p>Some languages may already have been fully translated, but lack proofreaders.</p><p>If you’re fluent in English and another language, and you’re interested in becoming a proofreader, join our <a href="https://discord.gg/vrPugybpJF" target="_blank" rel="noreferrer">Discord</a> and ask us being proofreader.</p></div><h2 id="code-contributions" tabindex="-1">Code contributions <a class="header-anchor" href="#code-contributions" aria-label="Permalink to &quot;Code contributions&quot;">​</a></h2><p>Want to have a more direct role in improving Axolotl-PM?</p><p>You can propose improvements using the GitHub pull request system.</p><p>Check out the <a href="/website/previews/9f14c22779bf/docs/developers/internals-docs-index">Axolotl-PM internals docs</a> section to get started.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Look on the bug tracker for <a href="https://github.com/axolotl-pm/PocketMine-MP/issues?q=is%3Aissue%20state%3Aopen%20label%3A%22Easy%20task%22" target="_blank" rel="noreferrer">issues labelled “Easy task”</a> to get started with. This will help you familiarise yourself with the codebase.</p></div><div class="info custom-block"><p class="custom-block-title">Note</p><p>Submit a <a href="https://github.com/axolotl-pm/PocketMine-MP/issues/new?template=feature-proposal.yml" target="_blank" rel="noreferrer">Feature Proposal</a> issue on GitHub to get the team’s feedback before starting work on any large changes.</p><p>As we may decline PRs that don’t suit Axolotl-PM’s goals, to avoid wasting your time or ours, it’s best if any big changes are discussed with the team before starting work on them.</p></div><h2 id="donating" tabindex="-1">Donating <a class="header-anchor" href="#donating" aria-label="Permalink to &quot;Donating&quot;">​</a></h2><p>Axolotl-PM is free, but it requires a lot of time and effort from unpaid volunteers to develop. Donations enable us to keep delivering support for new versions and adding features your players love.</p><p>Check out the <a href="https://github.com/axolotl-pm/PocketMine-MP/tree/stable?tab=readme-ov-file#donate" target="_blank" rel="noreferrer">GitHub README Donating</a> section for up to date donation methods.</p>',21)])])}const h=e(s,[["render",i]]);export{b as __pageData,h as default};
